static z_t3947_t z_io_stat(z_t106_t path) {
    z_t3947_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t1453_t* boxed = (z_t1453_t*)z_xmalloc(sizeof(z_t1453_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t3935_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t3935_t* boxed = (z_t3935_t*)z_xmalloc(sizeof(z_t3935_t));
    *boxed = fs;
    result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


